#!/usr/bin/env python3
import argparse
import json
from collections import defaultdict
from datetime import datetime, timezone, timedelta
from pathlib import Path

SEVERITY = {"low": 1, "medium": 2, "high": 3, "critical": 4}

def parse_time(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(timezone.utc)

def normalize(record):
    required = ["id", "indicator_type", "value", "source", "confidence", "first_seen", "last_seen"]
    missing = [k for k in required if k not in record]
    if missing:
        raise ValueError(f"missing required fields: {', '.join(missing)}")
    confidence = float(record["confidence"])
    if not 0 <= confidence <= 1:
        raise ValueError("confidence must be between 0 and 1")
    return {
        "id": str(record["id"]),
        "indicator_type": str(record["indicator_type"]).lower(),
        "value": str(record["value"]).strip(),
        "source": str(record["source"]),
        "confidence": confidence,
        "first_seen": parse_time(record["first_seen"]).isoformat(),
        "last_seen": parse_time(record["last_seen"]).isoformat(),
        "kev": bool(record.get("kev", False)),
        "asset_criticality": int(record.get("asset_criticality", 1)),
        "internet_exposed": bool(record.get("internet_exposed", False)),
        "ttp": record.get("ttp", None),
    }

def dedupe(records):
    merged = {}
    for r in records:
        key = (r["indicator_type"], r["value"])
        if key not in merged:
            merged[key] = dict(r)
            merged[key]["sources"] = [r["source"]]
        else:
            current = merged[key]
            current["confidence"] = max(current["confidence"], r["confidence"])
            if r["source"] not in current["sources"]:
                current["sources"].append(r["source"])
            current["kev"] = current["kev"] or r["kev"]
            current["asset_criticality"] = max(current["asset_criticality"], r["asset_criticality"])
            current["internet_exposed"] = current["internet_exposed"] or r["internet_exposed"]
            if current.get("ttp") is None and r.get("ttp") is not None:
                current["ttp"] = r["ttp"]
    return list(merged.values())

def prioritize(record):
    score = 0
    reasons = []
    if record["kev"]:
        score += 4
        reasons.append("known exploited vulnerability context")
    if record["internet_exposed"]:
        score += 3
        reasons.append("internet-exposed asset")
    score += min(record["asset_criticality"], 5)
    if record["asset_criticality"] >= 4:
        reasons.append("high asset criticality")
    if record["confidence"] >= 0.8:
        score += 2
        reasons.append("high-confidence intelligence")
    elif record["confidence"] < 0.4:
        reasons.append("low-confidence intelligence; review before high-impact action")
    if record.get("ttp"):
        score += 1
        reasons.append("behavioral context available")
    level = "low"
    if score >= 9: level = "critical"
    elif score >= 7: level = "high"
    elif score >= 4: level = "medium"
    return level, score, reasons

def build_report(records):
    normalized = [normalize(r) for r in records]
    deduped = dedupe(normalized)
    ranked = []
    for r in deduped:
        level, score, reasons = prioritize(r)
        ranked.append({**r, "priority": level, "priority_score": score, "reasons": reasons})
    ranked.sort(key=lambda x: (-x["priority_score"], x["indicator_type"], x["value"]))
    return {
        "record_count": len(records),
        "unique_indicator_count": len(ranked),
        "records": ranked,
        "analyst_notes": [
            "Validate high-impact indicators before enforcement.",
            "Preserve source provenance and timestamps when records are merged.",
            "Use low-confidence records as investigative leads rather than automatic blocking decisions."
        ]
    }

def main():
    p = argparse.ArgumentParser(description="Local defensive CTI fusion tool")
    p.add_argument("input", type=Path)
    p.add_argument("--output", type=Path, default=None)
    args = p.parse_args()
    data = json.loads(args.input.read_text(encoding="utf-8"))
    if not isinstance(data, list) or not all(isinstance(x, dict) for x in data):
        raise ValueError("input must be a JSON array of objects")
    report = build_report(data)
    rendered = json.dumps(report, indent=2)
    if args.output:
        args.output.write_text(rendered + "\n", encoding="utf-8")
    else:
        print(rendered)

if __name__ == "__main__":
    main()
